'use strict';

const express = require('express');
const { memoryStore } = require('./storage/memory');
const { sqliteStore } = require('./storage/sqlite');
const { validateStorageAdapter } = require('./storage/validator');
const { sendError } = require('./utils/errors');

const { createPlayersRouter } = require('./modules/players');
const { createLeaderboardRouter } = require('./modules/leaderboard');
const { createSavesRouter } = require('./modules/saves');
const { createMatchmakingRouter } = require('./modules/matchmaking');
const { createRoomsRouter } = require('./modules/rooms');

const SUPPORTED_MODULES = ['players', 'leaderboard', 'saves', 'matchmaking', 'rooms'];
const DEFAULT_MODULES = ['players', 'leaderboard', 'saves'];

/**
 * Creates the express-gamekit router with configured modules, storage, and auth.
 * 
 * @param {object} [config={}]
 * @param {object} [config.storage] - Storage adapter instance (defaults to memoryStore())
 * @param {string[]} [config.modules] - Array of enabled modules (defaults to players, leaderboard, saves)
 * @param {string} [config.apiKey] - Optional API key for x-api-key header authentication
 * @param {number} [config.matchmakingRatingRange=100] - Rating window for matchmaking pairing
 * @returns {import('express').Router}
 */
function gamekit(config = {}) {
  // 1. Storage setup & validation
  const storage = config.storage || memoryStore();
  validateStorageAdapter(storage);

  // 2. Modules validation
  const enabledModules = config.modules || DEFAULT_MODULES;
  if (!Array.isArray(enabledModules)) {
    throw new TypeError('Config option "modules" must be an array of module names');
  }

  for (const mod of enabledModules) {
    if (!SUPPORTED_MODULES.includes(mod)) {
      throw new Error(
        `Unknown module: "${mod}". Supported modules: ${SUPPORTED_MODULES.join(', ')}`
      );
    }
  }

  // 3. Create core router
  const router = express.Router();
  router.use(express.json());

  // 4. API Key Authentication middleware (if apiKey is provided)
  if (config.apiKey) {
    if (typeof config.apiKey !== 'string' || config.apiKey.trim().length === 0) {
      throw new TypeError('Config option "apiKey" must be a non-empty string');
    }
    const expectedKey = config.apiKey;

    router.use((req, res, next) => {
      const clientKey = req.headers['x-api-key'];
      if (!clientKey || clientKey !== expectedKey) {
        return sendError(res, 401, 'Unauthorized: Invalid or missing x-api-key header');
      }
      next();
    });
  }

  // 5. Mount enabled modules
  let roomsRouterInstance = null;

  if (enabledModules.includes('players')) {
    router.use('/players', createPlayersRouter({ storage }));
  }

  if (enabledModules.includes('leaderboard')) {
    router.use('/leaderboard', createLeaderboardRouter({ storage }));
  }

  if (enabledModules.includes('saves')) {
    router.use('/saves', createSavesRouter({ storage }));
  }

  if (enabledModules.includes('matchmaking')) {
    router.use(
      '/matchmaking',
      createMatchmakingRouter({
        storage,
        ratingRange: config.matchmakingRatingRange || 100
      })
    );
  }

  if (enabledModules.includes('rooms')) {
    roomsRouterInstance = createRoomsRouter({ storage });
    router.use('/rooms', roomsRouterInstance);
  }

  // If rooms module is enabled, expose attachWebSocket on the returned router
  if (roomsRouterInstance) {
    router.attachWebSocket = roomsRouterInstance.attachWebSocket;
  }

  // 6. Global error handler for JSON API consistency
  // eslint-disable-next-line no-unused-vars
  router.use((err, req, res, next) => {
    const status = err.status || err.statusCode || 500;
    const message = err.message || 'Internal Server Error';
    return sendError(res, status, message);
  });

  return router;
}

// Named exports alongside default function
gamekit.gamekit = gamekit;
gamekit.memoryStore = memoryStore;
gamekit.sqliteStore = sqliteStore;
gamekit.validateStorageAdapter = validateStorageAdapter;

module.exports = gamekit;
